from .arena import UNITS

log = logging.getLogger(__name__)

CHAR_UUID = "19B10001-E8F2-537E-4F6C-D104768A1214"
STOP = " "
STEERINGS = ("direkt", "taktik")
TACTICS = ("ram", "push_out", "flank", "circle", "retreat", "dodge", "hold")
# Bildrand ringsum (Arena-Einheiten), damit das Modell sieht, was knapp außerhalb liegt.
PAD = 80.0
WATCH_S = 0.05
# Frische Sitzung nach so vielen Runden: alte Bilder machen jede Anfrage langsamer, nützen aber nicht mehr.
SESSION_TURNS = 12
TURN_TIMEOUT_S = 45.0
# Ab dieser Geschwindigkeit (Einheiten/s) zeigt die Bewegung verlässlich, wohin die Front zeigt.
MOVE_SPEED = 60.0
MEASURE_S = 0.25
STUCK_S = 1.2
ALIGN = math.radians(30)
# Geschätzte Drehrate beim Drehen auf der Stelle; nur für die Länge eines Drehimpulses.
SPIN_RATE = math.radians(240)
EDGE_MARGIN = 50.0
CIRCLE_R = 250.0


class PilotError(Exception):
    """Klartext für den Reiter „KI“."""


@dataclass
class Body:
    present: bool = False
    pos: np.ndarray = field(default_factory=lambda: np.zeros(2, np.float32))
    vel: np.ndarray = field(default_factory=lambda: np.zeros(2, np.float32))
    radius: float = 40.0
    outline: np.ndarray | None = None
    hp: float = 0.0
    max_hp: float = 0.0
    outside: bool = False


@dataclass
class Snapshot:
    phase: str
    battle: int
    fighting: bool
    elapsed: float | None
    size: tuple[float, float] | None
    bounds: tuple[float, float, float, float] | None
    me: Body
    foe: Body
    ulti: str
    items: list[tuple[str, np.ndarray, float]]


class Bluetooth:
    """Schickt nur Wechsel: die Firmware hält den letzten Befehl, bis ein neuer kommt."""

    def __init__(self, name: str, dry_run: bool):
        self.name = name
        self.dry_run = dry_run
        self.client = None
        self.key = STOP
        self._lock = asyncio.Lock()

    async def connect(self) -> None:
        if self.dry_run:
            log.info("KI-Probelauf: „%s“ wird nicht verbunden, Tasten nur in der Konsole.", self.name)
            return
        from bleak import BleakClient, BleakScanner

        device = await BleakScanner.find_device_by_filter(lambda d, _ad: d.name == self.name, timeout=10)
        if device is None:
            raise PilotError(f"Roboter „{self.name}“ nicht gefunden. Einschalten und näher an den "
                             "Server-PC stellen, dann „Verbinden“.")
        self.client = BleakClient(device)
        await self.client.connect()

    async def send(self, key: str, force: bool = False) -> None:
        async with self._lock:
            if key == self.key and not force:
                return
            if self.dry_run:
                log.info("KI %s: Taste %r", self.name, key)
            else:
                if self.client is None or not self.client.is_connected:
                    raise PilotError(f"Bluetooth zu „{self.name}“ getrennt. „Verbinden“ drücken.")
                await self.client.write_gatt_char(CHAR_UUID, key.encode(), response=True)
            self.key = key

    async def close(self) -> None:
        with contextlib.suppress(Exception):
            await self.send(STOP, force=True)
        if self.client is not None:
            with contextlib.suppress(Exception):
                await self.client.disconnect()


class Heading:
    """Front des eigenen Roboters aus der eigenen Bewegung; die Kamera allein kennt sie nicht."""

    def __init__(self):
        self.angle: float | None = None
        self.key = STOP
        self.since = 0.0

    def update(self, key: str, me: Body, t: float) -> None:
        if key != self.key:
            self.key, self.since = key, t
            if key in ("a", "d"):
                # Drehen auf der Stelle macht jede alte Schätzung wertlos.
                self.angle = None
        speed = float(np.linalg.norm(me.vel))
        if key in ("w", "s") and me.present and speed > MOVE_SPEED and t - self.since >= MEASURE_S:
            angle = math.atan2(float(me.vel[1]), float(me.vel[0]))
            self.angle = angle if key == "w" else _wrap(angle + math.pi)

    def held(self, t: float) -> float:
        return t - self.since


def _wrap(a: float) -> float:
    return (a + math.pi) % (2 * math.pi) - math.pi


def _unit(v: np.ndarray) -> np.ndarray:
    n = float(np.linalg.norm(v))
    return v / n if n > 1e-6 else np.array([1.0, 0.0], np.float32)


class Driver:
    """Fährt eine vom Modell gewählte Taktik 20× pro Sekunde; das Modell selbst ist dafür zu langsam."""

    def __init__(self):
        self.tactic = "hold"
        self.side = 1
        self._pulse: list[tuple[str, float]] = []

    def set(self, tactic: str, side: int) -> None:
        self.tactic, self.side = tactic, side

    def key(self, snap: Snapshot, heading: Heading, t: float) -> str:
        while self._pulse and self._pulse[0][1] <= t:
            self._pulse.pop(0)
        if self._pulse:
            return self._pulse[0][0]
        me, foe = snap.me, snap.foe
        if self.tactic == "hold" or not me.present or snap.bounds is None:
            return STOP
        x0, y0, x1, y1 = snap.bounds
        margin = me.radius + EDGE_MARGIN
        center = np.array([(x0 + x1) / 2, (y0 + y1) / 2], np.float32)
        near_edge = not (x0 + margin < me.pos[0] < x1 - margin and y0 + margin < me.pos[1] < y1 - margin)
        if near_edge:
            # Randschutz geht vor jeder Taktik: eine Kante kostet mehr als ein verpasster Treffer.
            outward = _unit(me.pos - center)
            if heading.angle is not None:
                front = np.array([math.cos(heading.angle), math.sin(heading.angle)])
                if float(front @ outward) > 0.3:
                    return self._start([("s", 0.35)], t)
            target = center
        elif not foe.present and self.tactic != "retreat":
            return STOP
        else:
            target = self._target(snap, center)
        target = np.clip(target, [x0 + margin, y0 + margin], [x1 - margin, y1 - margin])
        if heading.angle is None:
            # Steckt der Roboter fest, zeigt Zurückfahren die Front genauso gut.
            if heading.key == "w" and heading.held(t) > STUCK_S:
                return self._start([("s", 0.4)], t)
            return "w" if heading.key not in ("a", "d") else self._start([("w", 0.4)], t)
        want = math.atan2(float(target[1] - me.pos[1]), float(target[0] - me.pos[0]))
        diff = _wrap(want - heading.angle)
        if abs(diff) < ALIGN:
            return "w"
        # Bildkoordinaten: y zeigt nach unten, positiver Winkel ist im Uhrzeigersinn, also rechts.
        spin = "d" if diff > 0 else "a"
        return self._start([(spin, min(0.6, max(0.1, abs(diff) / SPIN_RATE))), ("w", 0.4)], t)

    def _start(self, steps: list[tuple[str, float]], t: float) -> str:
        self._pulse = []
        for key, dur in steps:
            t += dur
            self._pulse.append((key, t))
        return self._pulse[0][0]

    def _target(self, snap: Snapshot, center: np.ndarray) -> np.ndarray:
        me, foe = snap.me, snap.foe
        gap = me.radius + foe.radius
        away = _unit(me.pos - foe.pos)
        if self.tactic == "push_out":
            out = _unit(foe.pos - center)
            # Erst auf die Mittelseite des Gegners, sonst schiebt man ihn zur Mitte statt hinaus.
            if float((me.pos - foe.pos) @ out) > -foe.radius:
                return foe.pos - out * (gap + 60)
            return foe.pos
        if self.tactic == "flank":
            perp = np.array([-away[1], away[0]]) * self.side
            point = foe.pos + perp * (gap + 80)
            return point if float(np.linalg.norm(point - me.pos)) > 90 else foe.pos
        if self.tactic == "circle":
            a = math.radians(40) * self.side
            rot = np.array([away[0] * math.cos(a) - away[1] * math.sin(a),
                            away[0] * math.sin(a) + away[1] * math.cos(a)])
            return foe.pos + rot * CIRCLE_R
        if self.tactic == "retreat":
            return me.pos + away * 250
        if self.tactic == "dodge":
            return me.pos + np.array([-away[1], away[0]]) * self.side * 200
        return foe.pos


class DriveArgs(BaseModel):
    direction: Literal["forward", "back", "left", "right"] = Field(
        description="forward/back fahren, left/right drehen auf der Stelle.")
    ms: int = Field(400, ge=100, le=1500, description="Dauer in Millisekunden, danach Stopp.")


class TacticArgs(BaseModel):
    tactic: Literal["ram", "push_out", "flank", "circle", "retreat", "dodge", "hold"] = Field(
        description="ram: rammen. push_out: von der Mittelseite aus Richtung Rand schieben. flank: seitlich "
                    "angreifen. circle: umkreisen. retreat: Abstand gewinnen. dodge: seitlich ausweichen. "
                    "hold: stehen bleiben.")
    side: Literal["left", "right"] = Field("right", description="Seite für flank, circle und dodge.")


class SayArgs(BaseModel):
    text: str = Field(description="Kurzer Spruch fürs Publikum, Deutsch, höchstens 80 Zeichen.")


def prompt(slot: int, steering: str) -> str:
    base = (
        f"Du steuerst live einen echten Hebocon-Roboter (Roboter {slot}) in einer Arena. Jede Runde "
        "bekommst du ein Draufsicht-Foto: dein Roboter ist grün umrandet und mit DU beschriftet, der "
        "Gegner rot. Die weiße Linie ist der Arenarand; außerhalb verliert man HP. Orange ist die "
        "schrumpfende erlaubte Zone. Gelbe Kreise heilen, graue Kreise sind Hindernisse und kosten HP. "
        "Ziel: den Gegner rammen und hinausschieben, selbst drinbleiben. Zusammenstöße kosten den "
        "Langsameren HP. Die Ulti (Laser) erst zünden, wenn sie bereit ist. "
        "Handle sofort mit den Werkzeugen und denke nur kurz; jede Sekunde zählt. Antworte danach mit "
        "höchstens einem kurzen Satz zu deinem Plan. Nutze say ab und zu für einen frechen, "
        "familienfreundlichen Spruch fürs Publikum."
    )
    if steering == "taktik":
        return base + (
            " Wähle mit set_tactic eine Taktik; ein schneller Regler fährt sie, bis du eine neue wählst, "
            "und hält dich dabei vom Rand fern. Wechsle nur, wenn die Lage es verlangt."
        )
    return base + (
        " Fahre mit drive. forward ist die Front deines Roboters; die geschätzte Fahrtrichtung steht im "
        "Text und ist im Bild ein grüner Pfeil. Ist sie unbekannt, kurz forward fahren und schauen. "
        "Du darfst in einer Runde mehrere drive-Aufrufe hintereinander machen."
    )


class Pilot:
    def __init__(self, app, slot: int, model: str, steering: str, robot: str, effort: str | None,
                 client_factory):
        self.app = app
        self.slot = slot
        self.model = model
        self.steering = steering
        self.robot = robot
        self.effort = effort
        self.client_factory = client_factory
        self.status = "Startet …"
        self.error: str | None = None
        self.calls = 0
        self.comment = ""
        self.bt = Bluetooth(robot, app.cfg.ai_dry_run)
        self.heading = Heading()
        self.driver = Driver()
        self._stopped = threading.Event()
        self._loop: asyncio.AbstractEventLoop | None = None
        self._task: asyncio.Task | None = None
        self._thread = threading.Thread(target=self._thread_main, name=f"pilot-{slot}", daemon=True)

    def start(self) -> None:
        self._thread.start()

    def stop(self) -> None:
        self._stopped.set()
        loop, task = self._loop, self._task
        if loop is not None and task is not None:
            with contextlib.suppress(RuntimeError):
                loop.call_soon_threadsafe(task.cancel)

    def join(self, timeout: float) -> None:
        if self._thread.is_alive():
            self._thread.join(timeout)

    def public(self) -> dict:
        return {"status": self.status, "error": self.error, "calls": self.calls, "comment": self.comment,
                "tactic": self.driver.tactic if self.steering == "taktik" else None,
                "key": self.bt.key.strip() or None}

    # ---------- Ablauf ----------

    def _thread_main(self) -> None:
        asyncio.run(self._guarded())

    async def _guarded(self) -> None:
        self._loop = asyncio.get_running_loop()
        self._task = asyncio.current_task()
        if self._stopped.is_set():
            return
        try:
            await self._main()
        except asyncio.CancelledError:
            self.status = "Gestoppt"
        except Exception as exc:  # noqa: BLE001 – der Reiter „KI“ soll den Grund zeigen, nicht nur „tot“.
            log.exception("KI-Pilot %d fehlgeschlagen", self.slot)
            self.error = str(exc) or type(exc).__name__
            self.status = "Fehler"

    async def _main(self) -> None:
        self.status = "Verbinde Roboter …"
        client = None
        tasks: list[asyncio.Task] = []
        try:
            await self.bt.connect()
            self.status = "Verbinde Copilot …"
            client = self.client_factory()
            await client.start()
            tasks = [asyncio.create_task(self._watch()), asyncio.create_task(self._think(client))]
            done, _ = await asyncio.wait(tasks, return_when=asyncio.FIRST_EXCEPTION)
            for task in done:
                task.result()
        finally:
            for task in tasks:
                task.cancel()
            await self.bt.close()
            if client is not None:
                with contextlib.suppress(Exception):
                    await client.stop()

    async def _watch(self) -> None:
        """Schnelle Schleife: Fahrtrichtung schätzen, Taktik fahren und außerhalb des Kampfs anhalten."""
        battle = None
        while True:
            snap = self.snapshot()
            t = time.monotonic()
            self.heading.update(self.bt.key, snap.me, t)
            if snap.battle != battle:
                battle = snap.battle
                self.driver.set("hold", 1)
            if not snap.fighting:
                await self.bt.send(STOP)
            elif self.steering == "taktik":
                await self.bt.send(self.driver.key(snap, self.heading, t))
            await asyncio.sleep(WATCH_S)

    async def _think(self, client) -> None:
        session = None
        battle = None
        turns = 0
        try:
            while True:
                snap = self.snapshot()
                if not snap.fighting:
                    self.status = "Bereit, wartet auf den Kampf"
                    await asyncio.sleep(0.2)
                    continue
                if snap.battle != battle or turns >= SESSION_TURNS:
                    if snap.battle != battle:
                        battle, self.calls = snap.battle, 0
                    if session is not None:
                        with contextlib.suppress(Exception):
                            await session.disconnect()
                    session = await self._session(client)
                    turns = 0
                if self.calls >= self.app.cfg.ai_max_calls:
                    self.status = "Anfragelimit für diesen Kampf erreicht"
                    self.driver.set("hold", 1)
                    await asyncio.sleep(0.5)
                    continue
                self.status = "Kämpft"
                started = time.monotonic()
                image = self.picture(snap)
                attachments = [{"type": "blob", "data": image, "mimeType": "image/jpeg"}] if image else None
                self.calls += 1
                turns += 1
                try:
                    reply = await session.send_and_wait(self.describe(snap), attachments=attachments,
                                                        timeout=TURN_TIMEOUT_S)
                except TimeoutError:
                    log.warning("KI-Pilot %d: Modell antwortet nicht rechtzeitig.", self.slot)
                    with contextlib.suppress(Exception):
                        await session.abort()
                    continue
                text = getattr(getattr(reply, "data", None), "content", None) or ""
                if text.strip():
                    self.comment = text.strip()[:200]
                await asyncio.sleep(max(0.0, self.app.cfg.ai_turn_s - (time.monotonic() - started)))
        finally:
            if session is not None:
                with contextlib.suppress(Exception):
                    await session.disconnect()

    async def _session(self, client):
        from copilot import PermissionHandler, ToolSet

        extra = {"reasoning_effort": self.effort} if self.effort else {}
        return await client.create_session(
            on_permission_request=PermissionHandler.approve_all, model=self.model, tools=self.tools(),
            system_message={"mode": "replace", "content": prompt(self.slot, self.steering)},
            # Nur die eigenen Werkzeuge: kein Dateizugriff, keine Shell auf dem Server-PC.
            available_tools=ToolSet().add_custom("*"), skip_custom_instructions=True, streaming=False,
            **extra,
        )

    # ---------- Werkzeuge fürs Modell ----------

    def tools(self) -> list:
        from copilot import define_tool

        async def drive(args: DriveArgs) -> str:
            if not self.snapshot().fighting:
                return "Gerade läuft kein Kampf; die Motoren bleiben aus."
            key = {"forward": "w", "back": "s", "left": "a", "right": "d"}[args.direction]
            await self.bt.send(key)
            end = time.monotonic() + args.ms / 1000
            while time.monotonic() < end and self.snapshot().fighting:
                await asyncio.sleep(WATCH_S)
            await self.bt.send(STOP)
            return "Erledigt. " + self.position(self.snapshot())

        async def stop() -> str:
            await self.bt.send(STOP)
            return "Angehalten."

        async def set_tactic(args: TacticArgs) -> str:
            self.driver.set(args.tactic, 1 if args.side == "right" else -1)
            return f"Taktik {args.tactic} aktiv."

        def ulti() -> str:
            try:
                self.app.act("ulti", {"player": self.slot})
            except Exception as exc:  # noqa: BLE001 – das Modell soll den Grund lesen und weitermachen.
                return f"Geht nicht: {exc}"
            return "Ulti gezündet."

        def say(args: SayArgs) -> str:
            self.app.act("say", {"player": self.slot, "text": args.text})
            return "Gesagt."

        common = [
            define_tool("ulti", description="Laser-Ulti auf den Gegner zünden (nur wenn bereit).",
                        handler=ulti, skip_permission=True),
            define_tool("say", description="Sprechblase über deinem Roboter auf der Bühne.", handler=say,
                        skip_permission=True),
        ]
        if self.steering == "taktik":
            return [define_tool("set_tactic", description="Taktik wählen, die der Regler fährt.",
                                handler=set_tactic, skip_permission=True), *common]
        return [define_tool("drive", description="Kurz fahren oder drehen, danach Stopp.", handler=drive,
                            skip_permission=True),
                define_tool("stop", description="Sofort anhalten.", handler=stop, skip_permission=True),
                *common]

    # ---------- Lagebild ----------

    def snapshot(self) -> Snapshot:
        app = self.app
        with app._lock:
            game = app.game
            arena = app.arena
            foe_id = 3 - self.slot
            bodies = {self.slot: Body(), foe_id: Body()}
            for o in app.robots:
                if o.id in bodies:
                    p = game.player(o.id) if game else None
                    bodies[o.id] = Body(bool(o.present), np.array(o.pos, np.float32),
                                        np.array(o.vel, np.float32), float(o.radius),
                                        None if o.outline is None else np.array(o.outline),
                                        p.hp if p else 0.0, app.cfg.start_hp,
                                        bool(p and p.outside_since is not None))
            t = time.monotonic()
            fighting = app.phase == "fight" and game is not None and not game.finished
            bounds = None
            if arena is not None:
                bounds = (0.0, 0.0, *arena.size)
                zone = game.zone(t) if game else None
                if zone is not None:
                    bounds = tuple(float(v) for v in zone)
            ulti = "nicht verfügbar"
            items = []
            if game is not None:
                p = game.player(self.slot)
                charge = game.ulti_charge(p)
                ulti = ("verbraucht" if p.ulti_used else "bereit" if game.ulti_ready(p)
                        else f"lädt {round(100 * min(1.0, charge))} %")
                items = [(i.kind, np.array(i.pos, np.float32), float(i.radius)) for i in game.items]
            elapsed = None
            if app.fight_start is not None:
                elapsed = max(0.0, (app.fight_end or t) - app.fight_start)
            return Snapshot(app.phase, app.battle, fighting, elapsed, None if arena is None else arena.size,
                            bounds, bodies[self.slot], bodies[foe_id], ulti, items)

    def position(self, snap: Snapshot) -> str:
        me, foe = snap.me, snap.foe
        if not me.present:
            return "Dein Roboter ist gerade nicht zu sehen."
        text = f"Du bei ({me.pos[0]:.0f}, {me.pos[1]:.0f})"
        if self.heading.angle is not None:
            text += f", Front zeigt {math.degrees(self.heading.angle) % 360:.0f}°"
        if foe.present:
            dist = float(np.linalg.norm(foe.pos - me.pos)) - me.radius - foe.radius
            text += f"; Gegner bei ({foe.pos[0]:.0f}, {foe.pos[1]:.0f}), Lücke {max(0.0, dist):.0f}"
        return text + "."

    def describe(self, snap: Snapshot) -> str:
        me, foe = snap.me, snap.foe
        lines = [f"Kampfzeit {snap.elapsed or 0:.0f} s. Koordinaten in Arena-Einheiten, x nach rechts, "
                 "y nach unten; 0° = rechts, 90° = unten."]
        if snap.size is not None:
            lines.append(f"Arena {snap.size[0]:.0f} × {snap.size[1]:.0f}.")
            if snap.bounds is not None and snap.bounds != (0.0, 0.0, *snap.size):
                x0, y0, x1, y1 = snap.bounds
                lines.append(f"Erlaubte Zone x {x0:.0f}–{x1:.0f}, y {y0:.0f}–{y1:.0f}.")
        lines.append(f"Du: {me.hp:.0f}/{me.max_hp:.0f} HP{', AUSSERHALB!' if me.outside else ''}. "
                     f"Gegner: {foe.hp:.0f}/{foe.max_hp:.0f} HP{', außerhalb' if foe.outside else ''}.")
        unknown = " Fahrtrichtung unbekannt." if self.heading.angle is None else ""
        lines.append(self.position(snap) + unknown)
        lines.append(f"Ulti: {snap.ulti}.")
        if self.steering == "taktik":
            lines.append(f"Aktuelle Taktik: {self.driver.tactic}.")
        for kind, pos, _r in snap.items:
            label = "Hindernis" if kind == "obstacle" else "Power-up"
            lines.append(f"{label} bei ({pos[0]:.0f}, {pos[1]:.0f}).")
        return "\n".join(lines)

    def picture(self, snap: Snapshot) -> str | None:
        frame = self.app.camera.latest()
        arena = self.app.arena
        if frame is None or arena is None:
            return None
        px = self.app.cfg.ai_image_px / (UNITS + 2 * PAD)
        img = arena.warp(frame.image, px, PAD)

        def pt(u) -> tuple[int, int]:
            return int((float(u[0]) + PAD) * px), int((float(u[1]) + PAD) * px)

        w, h = arena.size
        cv2.rectangle(img, pt((0, 0)), pt((w, h)), (255, 255, 255), 2)
        if snap.bounds is not None and snap.bounds != (0.0, 0.0, w, h):
            x0, y0, x1, y1 = snap.bounds
            cv2.rectangle(img, pt((x0, y0)), pt((x1, y1)), (0, 140, 255), 2)
        for kind, pos, r in snap.items:
            color = (140, 140, 140) if kind == "obstacle" else (0, 220, 255)
            cv2.circle(img, pt(pos), max(2, int(r * px)), color, 2)
        for body, color, label in ((snap.foe, (40, 40, 230), "GEGNER"), (snap.me, (60, 220, 60), "DU")):
            if not body.present:
                continue
            if body.outline is not None and len(body.outline):
                poly = np.array([pt(p) for p in body.outline], np.int32)
                cv2.polylines(img, [poly], True, color, 2)
            x, y = pt(body.pos)
            cv2.putText(img, label, (x - 20, y - int(body.radius * px) - 6), cv2.FONT_HERSHEY_SIMPLEX, 0.5,
                        (0, 0, 0), 3)
            cv2.putText(img, label, (x - 20, y - int(body.radius * px) - 6), cv2.FONT_HERSHEY_SIMPLEX, 0.5,
                        color, 1)
        if snap.me.present and self.heading.angle is not None:
            tip = snap.me.pos + np.array([math.cos(self.heading.angle), math.sin(self.heading.angle)]) * (
                snap.me.radius + 60)
            cv2.arrowedLine(img, pt(snap.me.pos), pt(tip), (60, 220, 60), 2, tipLength=0.3)
        ok, jpeg = cv2.imencode(".jpg", img, [cv2.IMWRITE_JPEG_QUALITY, 80])
        return base64.b64encode(jpeg.tobytes()).decode() if ok else None


class Pilots:
    """Konfiguration und laufende Piloten je Platz plus Copilot-Anmeldung und Modellliste."""

    def __init__(self, app):
        self.app = app
        self.mode = "mensch"
        self.config = {s: {"model": "", "steering": "taktik", "robot": f"{app.cfg.ai_robot_prefix}{s}"}
                       for s in (1, 2)}
        self.running: dict[int, Pilot] = {}
        # None = noch nicht geprüft; „prüft“ läuft gerade.
        self.login: dict = {"state": None, "user": "", "error": ""}
        self.models: list[dict] = []
        self.client_factory = self._client

    def _client(self):
        from copilot import CopilotClient

        token = self.app.cfg.ai_github_token
        return CopilotClient(github_token=token or None, log_level="warning")

    def probe(self) -> None:
        if self.login["state"] == "prüft":
            return
        self.login = {"state": "prüft", "user": "", "error": ""}
        threading.Thread(target=lambda: asyncio.run(self._probe()), name="ai-probe", daemon=True).start()

    async def _probe(self) -> None:
        client = self.client_factory()
        try:
            await client.start()
            auth = await client.get_auth_status()
            if not auth.isAuthenticated:
                self.login = {"state": "fehlt", "user": "", "error": auth.statusMessage
                              or "Nicht bei GitHub Copilot angemeldet. Auf dem Server-PC „copilot“ "
                                 "starten und /login ausführen oder HEBOCON_AI_GITHUB_TOKEN setzen."}
                return
            models = []
            for m in await client.list_models():
                if m.policy is not None and m.policy.state == "disabled":
                    continue
                if not m.capabilities.supports.vision:
                    continue
                efforts = m.supported_reasoning_efforts or []
                models.append({"id": m.id, "name": m.name,
                               "multiplier": m.billing.multiplier if m.billing else None,
                               "effort": "low" if "low" in efforts else None})
            self.models = models
            self.login = {"state": "ok", "user": auth.login or "", "error": ""}
        except Exception as exc:  # noqa: BLE001 – Grund im Reiter zeigen statt still zu scheitern.
            log.exception("Copilot-Anmeldung fehlgeschlagen")
            self.login = {"state": "fehler", "user": "", "error": f"Copilot nicht erreichbar: {exc}"}
        finally:
            with contextlib.suppress(Exception):
                await client.stop()

    def label(self, slot: int) -> str:
        model = self.config[slot]["model"]
        name = next((m["name"] for m in self.models if m["id"] == model), model)
        return f"KI · {name}"[:24] if name else "KI"

    def start(self, slot: int) -> None:
        self.stop(slot)
        cfg = self.config[slot]
        if not cfg["model"]:
            return
        effort = next((m["effort"] for m in self.models if m["id"] == cfg["model"]), None)
        pilot = Pilot(self.app, slot, cfg["model"], cfg["steering"], cfg["robot"], effort,
                      self.client_factory)
        self.running[slot] = pilot
        pilot.start()

    def stop(self, slot: int) -> None:
        pilot = self.running.pop(slot, None)
        if pilot is not None:
            pilot.stop()

    def stop_all(self, timeout: float = 0.0) -> None:
        pilots = list(self.running.values())
        for slot in list(self.running):
            self.stop(slot)
        for pilot in pilots:
            # Kurz warten, damit der letzte Stopp-Befehl noch per Bluetooth rausgeht.
            pilot.join(timeout)

    def public(self, ai_slots: tuple[int, ...]) -> dict:
        slots = []
        for s in (1, 2):
            pilot = self.running.get(s)
            info = pilot.public() if pilot else {
                "status": ("Modell wählen" if not self.config[s]["model"] else "Nicht verbunden")
                if s in ai_slots else "Aus", "error": None, "calls": 0, "comment": "", "tactic": None,
                "key": None}
            slots.append({"slot": s, "active": s in ai_slots, **self.config[s], **info})
        return {"mode": self.mode, "login": self.login, "models": self.models, "slots": slots,
                "dry_run": self.app.cfg.ai_dry_run, "max_calls": self.app.cfg.ai_max_calls}
